// Fail open: only drop on positive evidence of a duplicate. If Redis errored or job_id is missing, process the report anyway (a duplicate beats a lost report).
const jobId = $('Call End Speed To Lead Desert Comfort LiveKit').first().json.body.job_id;
const done = $('Check Speed To Lead Report Done (Redis)').first().json.doneValue;
const lease = $('Claim Speed To Lead Report Lease (Redis)').first().json;
const leaseVals = Object.values(lease || {}).filter((v) => typeof v === 'number');
const leaseCount = leaseVals.length ? leaseVals[0] : null;
const alreadyDone = done === 'true' || done === true;
const leaseTaken = leaseCount !== null && leaseCount > 1;
const noJobId = !jobId;
return [{ json: { is_new: noJobId || !(alreadyDone || leaseTaken), already_done: alreadyDone, lease_count: leaseCount, no_job_id: noJobId } }];

