// Builds both GHL bodies: PUT (contact id known) and upsert-by-phone (fallback). Never blanks an existing value; client_account is idempotent.
const body = $('Call End Speed To Lead Desert Comfort LiveKit').first().json.body || {};
const details = body.details || {};
const cid = String(body.contact_id || '').trim();
const validId = /^[A-Za-z0-9]{10,40}$/.test(cid);
const fields = [{ key: 'client_account', fieldValue: 'Desert Comfort HVAC' }];
if (details.address) fields.push({ key: 'service_address_desertcomfort', fieldValue: details.address });
const update = { customFields: fields };
const upsert = { locationId: 'YOUR_GHL_LOCATION_ID', country: 'US', phone: body.lead_phone_number, customFields: fields };
if (details.first_name) { update.firstName = details.first_name; upsert.firstName = details.first_name; }
if (details.last_name) { update.lastName = details.last_name; upsert.lastName = details.last_name; }
return [{ json: { has_contact_id: validId, contact_id: validId ? cid : '', update_body_json: JSON.stringify(update), upsert_body_json: JSON.stringify(upsert) } }];

// Builds the GHL note and the Slack/email texts once, for every outcome. The agent already wrote the finished report texts; this only falls back when they are missing (a crash alert, an old agent).
const b = $('Call End Speed To Lead Desert Comfort LiveKit').first().json.body || {};
const m = b.messages || {};
const out = String(b.outcome || '');
const crash = !!(b.checkup && b.checkup.crash_detected);
const unreached = ['voicemail', 'silent_pickup', 'no_answer'].includes(out);
const failedDial = out === 'dial_failed';
const LABEL = { booked_emergency: 'emergency appointment booked', booked_standard: 'standard appointment booked', qualified_not_booked: 'qualified, not booked', transferred: 'transferred to a human', out_of_area: 'outside the service area', no_meaningful_conversation: 'connected, no meaningful conversation', do_not_call: 'asked not to be contacted again', dead_air: 'connected but nobody spoke (dead air)', callback_requested: 'asked for a callback (a team member calls)', voicemail: 'went to voicemail', silent_pickup: 'picked up but nobody spoke', no_answer: 'no answer (the phone rang out)', dial_failed: 'the call could NOT be placed' };
const headline = crash ? 'the model failed mid-call (a diagnostic alert, not the final outcome)' : (LABEL[out] || out);
const lines = [`Speed to lead call, attempt ${b.attempt ?? '?'}: ${headline}.`];
if (b.outcome_reason) lines.push('Reason: ' + b.outcome_reason);
if (b.sip_status_code) lines.push('SIP code: ' + b.sip_status_code);
if (unreached && Number(b.attempt) === 3) lines.push('All 3 attempts used with no contact (calls plus a text). Marked exhausted; a team member needs to follow up.');
if (failedDial) lines.push('Nothing retries automatically. Check the number in GHL and the phone line.');
if (b.emergency_unbooked) lines.push('EMERGENCY CRITERIA MET - NOT BOOKED.');
if (b.flags && b.flags.consent_dispute) lines.push('POSSIBLE DATA MIX-UP: the lead says they never filled out a form.');
const duration = (b.call_duration_secs === null || b.call_duration_secs === undefined) ? 'unknown' : b.call_duration_secs + 's';
lines.push('', DateTime.now().setZone('America/Phoenix').toFormat('cccc d LLLL yyyy, h:mm a') + ' Phoenix time', 'Phone: ' + (b.lead_phone_number || ''), 'Duration: ' + duration, 'Room: ' + (b.room || ''), 'Recording: ' + (b.recording_consent || 'unknown'));
if (b.call_summary) lines.push('', 'Summary: ' + b.call_summary);
if (b.transcript_allowed && b.transcript_text) lines.push('', 'Transcript:', b.transcript_text);
else if (!unreached && !failedDial && !crash) lines.push('', '(No transcript kept: the lead did not agree to recording, so only this summary is saved.)');
const fallbackText = failedDial
  ? `⚠️ Speed To Lead - Call ${b.attempt ?? '?'} could NOT be placed\nPhone: ${b.lead_phone_number || ''}\nReason: ${b.outcome_reason || 'unknown'}${b.sip_status_code ? '\nSIP code: ' + b.sip_status_code : ''}\nNothing retries automatically. Check the number in GHL and the phone line.`
  : `Speed To Lead call - ${headline}\nPhone: ${b.lead_phone_number || ''}\nAttempt: ${b.attempt ?? '?'}\n(formatted message unavailable)`;
const rep = m.report || m.alert || {};
const attempt = Number(b.attempt);
return [{ json: {
  note_text: lines.join('\n'),
  send_messages: !unreached,
  slack_text: rep.slack_text || fallbackText,
  email_subject: rep.email_subject || ('Speed To Lead - ' + headline + ' - ' + (b.lead_phone_number || '')),
  email_text: rep.email_text || fallbackText,
  next_attempt: unreached && !crash && [1, 2, 3].includes(attempt),
  finished: 'call' + (attempt || ''),
} }];

