// Decide Call 2 Allowed - this workflow's own copy of Call 1's checks (Decide Call 1 Allowed), for Call 2. Writes nothing.
// Extra rule (SunPath): only call if the status is still no_answer_call_1, so a lead reached or booked during the wait is not called.
// Fail-closed: anything that can't be checked denies. alert = a person must look. Quiet hours: Call 2 is exempt (Admin's rule).
const cid = $('Set Resolved Contact Speed To Lead').first().json.contact_id;
const base = { contact_id: cid, phone: '', first_name: '', last_name: '', stage: '', room: '', allowed: false, alert: false, alert_text: '', decision: '', reason: '' };
const out = (decision, reason, extra = {}) => [{ json: { ...base, decision, reason, ...extra } }];
const denyAlert = (decision, reason) => out(decision, reason, { alert: true, alert_text: `Call 2 was NOT placed: ${reason}.` });

const cr = $('Get Contact For Call 2').first().json;
if (cr.statusCode !== 200 || !cr.body || !cr.body.contact) return denyAlert('fetch_failed', `could not read contact ${cid} from GHL (HTTP ${cr.statusCode})`);
const c = cr.body.contact;
base.phone = String(c.phone || '').trim();
base.first_name = String(c.firstName || '').trim();
base.last_name = String(c.lastName || '').trim();

const dnd = (c.dndSettings && c.dndSettings.Call) || {};
if (String(dnd.status || '').toLowerCase() === 'active') return out('denied_dnd', 'Call DND is active on this contact');

const cfg = {}; try { for (const it of $('Get Settings For Call 2').all()) { const r = it.json || {}; if (r.key) cfg[String(r.key).trim()] = r.value; } } catch (e) { /* unreadable: defaults below apply */ }
const field = (id) => { const f = (c.customFields || []).find((x) => x.id === id); return f ? String(f.value !== undefined ? f.value : (f.fieldValue ?? '')).trim().toLowerCase() : ''; };
let stage = field(cfg.stage_field_id || 'YOUR_GHL_FIELD_ID_STAGE');
if (!stage) { const legacy = field(cfg.lead_status_field_id || 'YOUR_GHL_FIELD_ID_LEAD_STATUS'); const booked = String(cfg.legacy_booked_statuses || 'booked_emergency,booked_standard').split(',').map((s) => s.trim()); stage = booked.includes(legacy) ? 'booked' : 'contact'; }
const eligible = String(cfg.speedtolead_eligible_stages || 'contact,lead').split(',').map((s) => s.trim().toLowerCase()).filter(Boolean);
const tag = String(cfg.human_contacted_tag || 'human-contacted').trim().toLowerCase();
const hasTag = (c.tags || []).map((t) => String(t).trim().toLowerCase()).includes(tag);
base.stage = stage;
const status = field(cfg.lead_status_field_id || 'YOUR_GHL_FIELD_ID_LEAD_STATUS');
if (status !== 'no_answer_call_1') return out('denied_status_changed', `status is now "${status || 'blank'}", not no_answer_call_1: the lead was reached or updated during the wait`);
if (!eligible.includes(stage)) return out('denied_stage', `stage "${stage}" is not eligible for speed-to-lead (${eligible.join('/')})`);
if (hasTag) return out('denied_human_reached', `contact carries the "${tag}" tag: a team member already reached this lead`);

if (!base.phone) return denyAlert('denied_no_phone', 'the contact has no phone number');
if (!/^\+1\d{10}$/.test(base.phone)) return denyAlert('denied_bad_phone', `the contact's phone "${base.phone.slice(0, 30)}" is not a US number in +1XXXXXXXXXX form`);

const lockItem = $('Check Active Call Lock For Call 2').first().json;
if (!lockItem || lockItem.error) return denyAlert('lock_check_failed', `could not read the active-call lock (${lockItem && lockItem.error ? String(lockItem.error.message || lockItem.error).slice(0, 200) : 'no result'})`);
if (lockItem.lockValue !== undefined && lockItem.lockValue !== null && String(lockItem.lockValue) !== '') return out('denied_active_call', 'this number is on a call or already being called');

const room = `out-_${base.phone.replace(/\D/g, '')}_${cid}-2-${Date.now()}`;
return out('allowed', `Call 2 allowed (stage ${stage})`, { allowed: true, room });

// Decide Text Allowed - the text after an unanswered Call 2, and whether to arm Call 3 (the GHL 12 h tag). Writes nothing.
// Same rules as the old Next Attempt workflow: no text if SMS is blocked or texts are switched off, but Call 3 is still armed;
// nothing at all if the lead is resolved (booked / a person reached them). Sent right away (Admin's rule). Unreadable contact = alert.
const cid = $('Set Resolved Contact Speed To Lead').first().json.contact_id;
const cfg = {}; try { for (const it of $('Get Settings For Text').all()) { const r = it.json || {}; if (r.key) cfg[String(r.key).trim()] = r.value; } } catch (e) { /* unreadable: defaults below apply */ }
const cr = $('Get Contact For Text').first().json;
if (cr.statusCode !== 200 || !cr.body || !cr.body.contact) return [{ json: { action: 'alert', contact_id: cid, phone: '', decision: 'fetch_failed', reason: `could not read contact from GHL (HTTP ${cr.statusCode})`, alert_text: `The text after Call 2 was NOT sent and Call 3 was NOT armed: could not read contact ${cid} from GHL (HTTP ${cr.statusCode}).` } }];
const c = cr.body.contact;
const phone = String(c.phone || '').trim();
const field = (id) => { const f = (c.customFields || []).find((x) => x.id === id); return f ? String(f.value !== undefined ? f.value : (f.fieldValue ?? '')).trim().toLowerCase() : ''; };
let stage = field(cfg.stage_field_id || 'YOUR_GHL_FIELD_ID_STAGE');
if (!stage) { const legacy = field(cfg.lead_status_field_id || 'YOUR_GHL_FIELD_ID_LEAD_STATUS'); const booked = String(cfg.legacy_booked_statuses || 'booked_emergency,booked_standard').split(',').map((s) => s.trim()); stage = booked.includes(legacy) ? 'booked' : 'contact'; }
const eligible = String(cfg.speedtolead_eligible_stages || 'contact,lead').split(',').map((s) => s.trim().toLowerCase()).filter(Boolean);
const tag = String(cfg.human_contacted_tag || 'human-contacted').trim().toLowerCase();
const hasTag = (c.tags || []).map((t) => String(t).trim().toLowerCase()).includes(tag);
const res = (action, decision, reason) => [{ json: { action, contact_id: cid, phone, stage, decision, reason, alert_text: '' } }];
if (!eligible.includes(stage)) return res('none', 'denied_stage', `stage "${stage}" is not eligible: no text, no Call 3`);
if (hasTag) return res('none', 'denied_human_reached', `the "${tag}" tag is on: a team member already reached this lead`);
if (String(cfg.speedtolead_text_enabled ?? 'true').trim().toLowerCase() === 'false') return res('tag_only', 'text_disabled', 'texts are switched off in config (speedtolead_text_enabled); Call 3 armed');
const sms = (c.dndSettings && c.dndSettings.SMS) || {};
if (c.dnd === true || String(sms.status || '').toLowerCase() === 'active') return res('tag_only', 'denied_dnd_sms', 'SMS DND is active: no text; Call 3 armed');
if (!/^\+1\d{10}$/.test(phone)) return res('tag_only', 'denied_bad_phone', `no usable US number ("${phone.slice(0, 30)}"): no text; Call 3 armed`);
return res('send', 'allowed', 'text after Call 2 allowed');

// Build Text Message - the wording lives in config (speedtolead_text_body); {first_name} becomes 'there' without a real name.
const c = ($('Get Contact For Text').first().json.body || {}).contact || {};
const cfg = {}; try { for (const it of $('Get Settings For Text').all()) { const r = it.json || {}; if (r.key) cfg[String(r.key).trim()] = r.value; } } catch (e) { /* unreadable: defaults below apply */ }
const first = String(c.firstName || '').trim();
const real = first && !/^(not captured|unknown|n\/a|none)$/i.test(first);
const tpl = String(cfg.speedtolead_text_body || 'Hi {first_name}, this is Desert Comfort HVAC. We tried to reach you about your service request. You can call or text this number anytime. Reply STOP to opt out.');
return [{ json: { from: String(cfg.speedtolead_sms_from || 'YOUR_BUSINESS_PHONE_NUMBER'), to: String(c.phone || ''), text: tpl.split('{first_name}').join(real ? first : 'there') } }];

// Decide Exhausted - flag the lead for a person only if they are still an open speed-to-lead lead (same stage + human-tag rules as Call 1).
// If GHL can't be read, flag anyway: a person checking is harmless, a missed lead is not. The exhausted status was already written by the outcome branch.
const cid = $('Set Resolved Contact Speed To Lead').first().json.contact_id;
const phone = String($('Call End Speed To Lead Desert Comfort LiveKit').first().json.body.lead_phone_number || '');
const cr = $('Get Contact For Exhausted').first().json;
if (cr.statusCode !== 200 || !cr.body || !cr.body.contact) return [{ json: { applies: true, stage: 'unknown', name: 'the lead', phone, reason: `could not re-read the contact from GHL (HTTP ${cr.statusCode}); flagged anyway` } }];
const c = cr.body.contact;
const cfg = {}; try { for (const it of $('Get Settings For Exhausted').all()) { const r = it.json || {}; if (r.key) cfg[String(r.key).trim()] = r.value; } } catch (e) { /* unreadable: defaults below apply */ }
const field = (id) => { const f = (c.customFields || []).find((x) => x.id === id); return f ? String(f.value !== undefined ? f.value : (f.fieldValue ?? '')).trim().toLowerCase() : ''; };
let stage = field(cfg.stage_field_id || 'YOUR_GHL_FIELD_ID_STAGE');
if (!stage) { const legacy = field(cfg.lead_status_field_id || 'YOUR_GHL_FIELD_ID_LEAD_STATUS'); const booked = String(cfg.legacy_booked_statuses || 'booked_emergency,booked_standard').split(',').map((s) => s.trim()); stage = booked.includes(legacy) ? 'booked' : 'contact'; }
const eligible = String(cfg.speedtolead_eligible_stages || 'contact,lead').split(',').map((s) => s.trim().toLowerCase()).filter(Boolean);
const tag = String(cfg.human_contacted_tag || 'human-contacted').trim().toLowerCase();
const hasTag = (c.tags || []).map((t) => String(t).trim().toLowerCase()).includes(tag);
const applies = eligible.includes(stage) && !hasTag;
const name = [c.firstName, c.lastName].filter(Boolean).join(' ').trim() || 'the lead';
return [{ json: { applies, stage, name, phone: c.phone || phone, reason: applies ? 'still an open lead after Call 3' : (hasTag ? 'a team member already reached this lead' : `stage is now "${stage}"`) } }];

// Extract Outbound Lead Fields - only the contact id is taken from GHL's webhook body; name and phone are re-read from GHL by id after the wait
// (never trust the body). Never throws: bad input becomes `problem`.
const body = ($input.first().json || {}).body || {};
const contact_id = String(body.contact_id || body.contactId || body.id || '').trim();
const first_name = String(body.first_name || body.firstName || '').trim();
const last_name = String(body.last_name || body.lastName || '').trim();
let problem = '';
if (!contact_id) problem = 'GHL sent no contact_id';
else if (!/^[A-Za-z0-9]{10,40}$/.test(contact_id)) problem = `contact_id "${contact_id.slice(0, 60)}" is not a valid GHL id`;
return [{ json: { contact_id, first_name, last_name, valid: !problem, problem } }];

// Decide Call 1 Allowed - this workflow's own copy of the Contact Gate's speed-to-lead checks (Desert Comfort Contact Gate > Decide Gate,
// 2026-10-30), Call 1 only. Reads through explicit node references, writes nothing. Fail-closed: anything that can't be checked denies.
// alert = a person must look (the lead was NOT called for a reason that is not the lead's own choice). Quiet hours: Call 1 is exempt (Admin's rule).
const lead = $('Extract Outbound Lead Fields').first().json;
const base = { contact_id: lead.contact_id, phone: '', first_name: lead.first_name, last_name: lead.last_name, stage: '', room: '', allowed: false, alert: false, alert_text: '', decision: '', reason: '' };
const out = (decision, reason, extra = {}) => [{ json: { ...base, decision, reason, ...extra } }];
const denyAlert = (decision, reason) => out(decision, reason, { alert: true, alert_text: `Call 1 was NOT placed: ${reason}.` });

const cr = $('Get Contact For Call 1').first().json;
if (cr.statusCode !== 200 || !cr.body || !cr.body.contact) return denyAlert('fetch_failed', `could not read contact ${lead.contact_id} from GHL (HTTP ${cr.statusCode})`);
const contact = cr.body.contact;
base.phone = String(contact.phone || '').trim();
base.first_name = String(contact.firstName || '').trim() || lead.first_name;
base.last_name = String(contact.lastName || '').trim() || lead.last_name;

const dnd = (contact.dndSettings && contact.dndSettings.Call) || {};
if (String(dnd.status || '').toLowerCase() === 'active') return out('denied_dnd', 'Call DND is active on this contact');

const cfg = {};
try { for (const it of $('Get Speed To Lead Settings').all()) { const r = it.json || {}; if (r.key) cfg[String(r.key).trim()] = r.value; } } catch (e) { /* settings unreadable: the built-in defaults below apply */ }
const field = (id) => { const f = (contact.customFields || []).find((x) => x.id === id); return f ? String(f.value !== undefined ? f.value : (f.fieldValue ?? '')).trim().toLowerCase() : ''; };
let stage = field(cfg.stage_field_id || 'YOUR_GHL_FIELD_ID_STAGE');
if (!stage) {
  // contact from before the stage field existed: same legacy fallback as the Contact Gate
  const legacy = field(cfg.lead_status_field_id || 'YOUR_GHL_FIELD_ID_LEAD_STATUS');
  const booked = String(cfg.legacy_booked_statuses || 'booked_emergency,booked_standard').split(',').map((s) => s.trim());
  stage = booked.includes(legacy) ? 'booked' : 'contact';
}
base.stage = stage;
const eligible = String(cfg.speedtolead_eligible_stages || 'contact,lead').split(',').map((s) => s.trim().toLowerCase()).filter(Boolean);
if (!eligible.includes(stage)) return out('denied_stage', `stage "${stage}" is not eligible for speed-to-lead (${eligible.join('/')})`);

const tag = String(cfg.human_contacted_tag || 'human-contacted').trim().toLowerCase();
if ((contact.tags || []).map((t) => String(t).trim().toLowerCase()).includes(tag)) return out('denied_human_reached', `contact carries the "${tag}" tag: a team member already reached this lead`);

if (!base.phone) return denyAlert('denied_no_phone', 'the contact has no phone number');
if (!/^\+1\d{10}$/.test(base.phone)) return denyAlert('denied_bad_phone', `the contact's phone "${base.phone.slice(0, 30)}" is not a US number in +1XXXXXXXXXX form`);

const lockItem = $('Check Active Call Lock').first().json;
if (!lockItem || lockItem.error) return denyAlert('lock_check_failed', `could not read the active-call lock (${lockItem && lockItem.error ? String(lockItem.error.message || lockItem.error).slice(0, 200) : 'no result'})`);
if (lockItem.lockValue !== undefined && lockItem.lockValue !== null && String(lockItem.lockValue) !== '') return out('denied_active_call', 'this number is on a call or already being called');

const room = `out-_${base.phone.replace(/\D/g, '')}_${lead.contact_id}-1-${Date.now()}`;
return out('allowed', `Call 1 allowed (stage ${stage})`, { allowed: true, room });

